#!/usr/bin/env python3
"""Regenerate design/vendor/seti-map.js from upstream Seti UI sources.

Joins two MIT-licensed inputs:
  jesseweed/seti-ui   mapping.less     extension  -> icon name + colour variable
                      ui-variables.less colour variable -> hex
  microsoft/vscode    vs-seti-icon-theme.json  icon name -> font codepoint,
                                               plus light-theme colour overrides

Run from the repository root:  uv run --no-project python design/vendor/build-seti-map.py
"""

import json
import re
import urllib.request
from pathlib import Path
from textwrap import dedent

SETI = "https://raw.githubusercontent.com/jesseweed/seti-ui/master/styles/"
VSCODE = (
    "https://raw.githubusercontent.com/microsoft/vscode/main/extensions/"
    "theme-seti/icons/vs-seti-icon-theme.json"
)
OUT = Path(__file__).parent / "seti-map.js"


def get(url: str) -> str:
    with urllib.request.urlopen(url, timeout=30) as r:
        return r.read().decode()


def main() -> None:
    theme = json.loads(get(VSCODE))
    defs = theme["iconDefinitions"]

    # icon name -> codepoint, e.g. "_bsl" -> "e00a"
    char = {
        k.lstrip("_"): v["fontCharacter"].replace("\\", "").lower()
        for k, v in defs.items()
        if not k.endswith("_light")
    }
    colors = dict(
        re.findall(r"^@([\w-]+):\s*(#[0-9a-fA-F]{3,8});", get(SETI + "ui-variables.less"), re.M)
    )

    ext: dict[str, list[str]] = {}
    names: dict[str, list[str]] = {}
    for target, icon, col in re.findall(
        r'\.icon-set\("([^"]+)",\s*"([^"]+)",\s*@([\w-]+)\)',
        get(SETI + "components/icons/mapping.less"),
    ):
        if (code := char.get(icon)) is None:
            continue
        entry = [code, colors.get(col, "#d4d7d6")]
        bare = target.lstrip(".")
        # a leading dot with no further dots means "file extension", else "exact name"
        (ext if target.startswith(".") and "." not in bare else names)[bare.lower()] = entry

    light = {
        e: color
        for e, key in theme["light"]["fileExtensions"].items()
        if e in ext and (color := defs.get(key, {}).get("fontColor"))
    }

    payload = {
        "ext": ext,
        "name": names,
        "light": light,
        "default": [defs["_default"]["fontCharacter"].replace("\\", "").lower(), colors["white"]],
    }
    OUT.write_text(
        dedent("""\
            /* Generated by build-seti-map.py — do not edit by hand.
               Sources: jesseweed/seti-ui (MIT) + microsoft/vscode theme-seti (MIT).
               See SETI-LICENSE.md.
                 ext     extension       -> [codepoint, dark colour]
                 name    exact file name -> [codepoint, dark colour]
                 light   extension       -> light-theme colour override
            */
            window.SETI = """)
        + json.dumps(payload, separators=(",", ":"), sort_keys=True)
        + ";\n"
    )
    print(f"{len(ext)} extensions, {len(names)} names, {len(light)} light overrides -> {OUT}")


if __name__ == "__main__":
    main()
